-- Creates and links mobile-app accounts only for imported FIT90 members with a usable unique phone number.
-- Login endpoint: POST /mobile/app/login with {"phone":"stored phone","password":"phone digits only"}.
-- Passwords below are bcrypt hashes (cost 12); no plaintext passwords are written to this file.
-- Safe rerun: existing linked accounts are left untouched. The script stops before changes if a conflicting api_users phone already exists.
SET NAMES utf8mb4;
SET @target_branch_id := 1;
SET @expected_database := 'metacodecx_fit90';

CREATE TEMPORARY TABLE `_fit90_mobile_account_import` (
  `legacy_member_id` VARCHAR(30) NOT NULL,
  `name` VARCHAR(200) NOT NULL,
  `phone` VARCHAR(20) NOT NULL,
  `email` VARCHAR(150) NULL,
  `password_hash` VARCHAR(500) NOT NULL,
  PRIMARY KEY (`legacy_member_id`),
  UNIQUE KEY `uq_fit90_mobile_phone` (`phone`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;















SELECT (BINARY DATABASE() = BINARY @expected_database) INTO @database_ok;
SELECT EXISTS(
  SELECT 1 FROM `tbl_branches`
  WHERE `branch_id` = @target_branch_id
    AND BINARY LOWER(TRIM(`branch_name`)) = BINARY 'fit90'
) INTO @branch_ok;

-- An account already owned by another member or duplicate app-account phone is unsafe.
-- An unlinked matching account is a legacy/test account and is safely converted to the real member account below.
SELECT COUNT(*) INTO @unsafe_account_ownership_conflicts
FROM `_fit90_mobile_account_import` i
JOIN `club_members` m
  ON m.`member_code` = CONCAT('MIG-', i.`legacy_member_id`)
 AND m.`phone` = i.`phone`
JOIN `api_users` a ON a.`user_phone` = i.`phone`
JOIN `club_members` owner
  ON owner.`app_user_id` = a.`user_id`
 AND owner.`id` <> m.`id`
 AND owner.`is_deleted` = 0
WHERE m.`branch_id` = @target_branch_id
  AND m.`is_deleted` = 0
  AND m.`app_user_id` IS NULL;

SELECT COUNT(*) INTO @duplicate_existing_app_accounts
FROM (
  SELECT i.`phone`
  FROM `_fit90_mobile_account_import` i
  JOIN `club_members` m
    ON m.`member_code` = CONCAT('MIG-', i.`legacy_member_id`)
   AND m.`phone` = i.`phone`
  JOIN `api_users` a ON a.`user_phone` = i.`phone`
  WHERE m.`branch_id` = @target_branch_id
    AND m.`is_deleted` = 0
    AND m.`app_user_id` IS NULL
  GROUP BY i.`phone`
  HAVING COUNT(*) > 1
) AS duplicate_phones;

SET @is_safe := @database_ok AND @branch_ok
  AND @unsafe_account_ownership_conflicts = 0
  AND @duplicate_existing_app_accounts = 0;
SELECT @is_safe AS `precheck_passed`, @database_ok AS `database_ok`, @branch_ok AS `branch_ok`,
  @unsafe_account_ownership_conflicts AS `accounts_owned_by_another_member`,
  @duplicate_existing_app_accounts AS `duplicate_existing_app_accounts`;

START TRANSACTION;

-- Convert an unlinked legacy/test account with the same phone into the member's real app account.
UPDATE `api_users` a
JOIN `_fit90_mobile_account_import` i ON a.`user_phone` = i.`phone`
JOIN `club_members` m
  ON m.`member_code` = CONCAT('MIG-', i.`legacy_member_id`)
 AND m.`phone` = i.`phone`
LEFT JOIN `club_members` owner
  ON owner.`app_user_id` = a.`user_id`
 AND owner.`is_deleted` = 0
SET a.`user_name` = LEFT(i.`name`, 100),
    a.`user_email` = NULLIF(LEFT(i.`email`, 70), ''),
    a.`user_pass` = i.`password_hash`,
    a.`status` = 1
WHERE @is_safe = 1
  AND m.`branch_id` = @target_branch_id
  AND m.`is_deleted` = 0
  AND m.`app_user_id` IS NULL
  AND owner.`id` IS NULL;
SELECT ROW_COUNT() AS `existing_test_accounts_converted`;

SELECT LEFT(i.`name`, 100), i.`phone`, NULLIF(LEFT(i.`email`, 70), ''), i.`password_hash`, 1
FROM `_fit90_mobile_account_import` i
JOIN `club_members` m
  ON m.`member_code` = CONCAT('MIG-', i.`legacy_member_id`)
 AND m.`phone` = i.`phone`
LEFT JOIN `api_users` a ON a.`user_phone` = i.`phone`
WHERE @is_safe = 1
  AND m.`branch_id` = @target_branch_id
  AND m.`is_deleted` = 0
  AND m.`app_user_id` IS NULL
  AND a.`user_id` IS NULL;
SELECT ROW_COUNT() AS `mobile_app_accounts_created`;

UPDATE `club_members` m
JOIN `_fit90_mobile_account_import` i
  ON m.`member_code` = CONCAT('MIG-', i.`legacy_member_id`)
 AND m.`phone` = i.`phone`
JOIN `api_users` a ON a.`user_phone` = i.`phone`
SET m.`app_user_id` = a.`user_id`, m.`updated_at` = NOW(3)
WHERE @is_safe = 1
  AND m.`branch_id` = @target_branch_id
  AND m.`is_deleted` = 0
  AND m.`app_user_id` IS NULL;
SELECT ROW_COUNT() AS `members_linked_to_mobile_app_accounts`;

COMMIT;

SELECT
  2834 AS `migration_rows_considered`,
  2772 AS `members_with_usable_unique_phone_in_source`,
  62 AS `source_rows_without_usable_phone`,
  (SELECT COUNT(*)
   FROM `club_members` m
   JOIN `_fit90_mobile_account_import` i
     ON m.`member_code` = CONCAT('MIG-', i.`legacy_member_id`)
    AND m.`phone` = i.`phone`
   JOIN `api_users` a ON m.`app_user_id` = a.`user_id`
   WHERE m.`branch_id` = @target_branch_id
     AND m.`is_deleted` = 0
     AND a.`status` = 1) AS `active_linked_members_after_run`;

DROP TEMPORARY TABLE `_fit90_mobile_account_import`;
